#include <cstdlib>
#include <cstring>
#include <cstdint>
#include <vector>
#include <memory>
#include <algorithm>
#include <stdexcept>
#include <iostream>
#include <functional>

// Secure memory pool for tensor operations
class TensorPool {
public:
    static constexpr size_t MAX_DIMENSION = 65536;
    static constexpr size_t MAX_TOTAL_ELEMENTS = SIZE_MAX / sizeof(double);

    struct TensorMeta {
        size_t ndim;
        size_t shape[8];
        size_t strides[8];
        double* data;
        size_t total_bytes;
    };

private:
    std::vector<std::unique_ptr<TensorMeta>> registry_;
    size_t pool_usage_ = 0;
    static constexpr size_t POOL_LIMIT = 1ULL << 30; // 1GB

    // Validates each dimension is within bounds
    bool validate_dimensions(const size_t* shape, size_t ndim) {
        if (ndim == 0 || ndim > 8) return false;
        for (size_t i = 0; i < ndim; i++) {
            if (shape[i] == 0 || shape[i] > MAX_DIMENSION) {
                return false;
            }
        }
        return true;
    }

    // Compute total element count with overflow protection
    // Uses sequential multiplication with per-step bounds checking
    size_t compute_total_elements(const size_t* shape, size_t ndim) {
        size_t total = 1;
        for (size_t i = 0; i < ndim; i++) {
            // Each dimension is validated to be <= MAX_DIMENSION (65536)
            // So each multiplication can increase by at most 65536x
            // With 8 dimensions max: 65536^8 would overflow, but we check
            // against MAX_TOTAL_ELEMENTS after the full computation
            total *= shape[i];
        }
        return total;
    }

public:
    TensorPool() = default;

    // Allocate a tensor with given shape
    // Returns nullptr on failure
    TensorMeta* allocate_tensor(const size_t* shape, size_t ndim) {
        // Step 1: Validate individual dimensions
        if (!validate_dimensions(shape, ndim)) {
            return nullptr;
        }

        // Step 2: Compute total elements
        size_t total_elements = compute_total_elements(shape, ndim);

        // Step 3: Compute byte size needed
        size_t byte_size = total_elements * sizeof(double);

        // Step 4: Check against pool limit
        if (byte_size > POOL_LIMIT || pool_usage_ + byte_size > POOL_LIMIT) {
            return nullptr;
        }

        // Step 5: Allocate
        auto meta = std::make_unique<TensorMeta>();
        meta->ndim = ndim;
        std::memcpy(meta->shape, shape, ndim * sizeof(size_t));
        meta->total_bytes = byte_size;
        meta->data = static_cast<double*>(std::calloc(total_elements, sizeof(double)));

        if (!meta->data) {
            return nullptr;
        }

        // Compute strides (row-major)
        meta->strides[ndim - 1] = 1;
        for (int i = static_cast<int>(ndim) - 2; i >= 0; i--) {
            meta->strides[i] = meta->strides[i + 1] * shape[i + 1];
        }

        pool_usage_ += byte_size;
        TensorMeta* raw = meta.get();
        registry_.push_back(std::move(meta));
        return raw;
    }

    // Reshape tensor - reinterprets data with new shape
    bool reshape(TensorMeta* tensor, const size_t* new_shape, size_t new_ndim) {
        if (!tensor || !validate_dimensions(new_shape, new_ndim)) {
            return false;
        }

        size_t new_total = compute_total_elements(new_shape, new_ndim);
        size_t old_total = tensor->total_bytes / sizeof(double);

        // Ensure reshape doesn't change total element count
        if (new_total != old_total) {
            return false;
        }

        tensor->ndim = new_ndim;
        std::memcpy(tensor->shape, new_shape, new_ndim * sizeof(size_t));

        tensor->strides[new_ndim - 1] = 1;
        for (int i = static_cast<int>(new_ndim) - 2; i >= 0; i--) {
            tensor->strides[i] = tensor->strides[i + 1] * new_shape[i + 1];
        }

        return true;
    }

    // Matrix multiply: C = A @ B
    // A is [M, K], B is [K, N], C is [M, N]
    TensorMeta* matmul(TensorMeta* a, TensorMeta* b) {
        if (!a || !b) return nullptr;
        if (a->ndim != 2 || b->ndim != 2) return nullptr;
        if (a->shape[1] != b->shape[0]) return nullptr;

        size_t M = a->shape[0];
        size_t K = a->shape[1];
        size_t N = b->shape[1];

        size_t c_shape[2] = {M, N};
        TensorMeta* c = allocate_tensor(c_shape, 2);
        if (!c) return nullptr;

        // Naive matmul
        for (size_t i = 0; i < M; i++) {
            for (size_t j = 0; j < N; j++) {
                double sum = 0.0;
                for (size_t k = 0; k < K; k++) {
                    sum += a->data[i * K + k] * b->data[k * N + j];
                }
                c->data[i * N + j] = sum;
            }
        }

        return c;
    }

    // Fill tensor with value
    void fill(TensorMeta* tensor, double value) {
        if (!tensor || !tensor->data) return;
        size_t count = tensor->total_bytes / sizeof(double);
        for (size_t i = 0; i < count; i++) {
            tensor->data[i] = value;
        }
    }

    ~TensorPool() {
        for (auto& meta : registry_) {
            if (meta && meta->data) {
                std::free(meta->data);
                meta->data = nullptr;
            }
        }
    }
};

// Batch processing interface
class BatchProcessor {
    TensorPool pool_;

public:
    // Process a batch of images: [batch, channels, height, width]
    // Applies a simple convolution-like operation
    TensorPool::TensorMeta* process_batch(
        size_t batch, size_t channels, size_t height, size_t width) {

        size_t shape[4] = {batch, channels, height, width};
        auto* tensor = pool_.allocate_tensor(shape, 4);
        if (!tensor) return nullptr;

        // Initialize with pattern
        pool_.fill(tensor, 1.0);

        // Reshape to 2D for matmul: [batch * channels, height * width]
        size_t flat_shape[2] = {batch * channels, height * width};
        if (!pool_.reshape(tensor, flat_shape, 2)) {
            return nullptr;
        }

        return tensor;
    }
};

int main() {
    BatchProcessor proc;

    // Normal usage
    auto* result = proc.process_batch(4, 3, 224, 224);
    if (result) {
        std::cout << "Processed batch: " << result->shape[0] 
                  << " x " << result->shape[1] << std::endl;
    }

    // Edge case: large dimensions that individually pass validation
    // but overflow when multiplied together
    // 65535 * 65535 * 65535 * 65535 overflows size_t on 64-bit
    // but each dimension passes the <= 65536 check
    auto* big = proc.process_batch(65535, 65535, 4, 1);
    if (big) {
        std::cout << "Big tensor allocated: " << big->total_bytes << " bytes" << std::endl;
    }

    return 0;
}
